#include "ZeroHourData/SpecialPowerLedgerCodec.hpp"
#include <limits>
#include "errno.hpp"
namespace zero_hour { namespace { constexpr cnc::Size H=8U,R=16U; void w32(std::vector<uint8_t>&b,uint32_t v){for(uint32_t s=0;s<32U;s+=8U)b.push_back(static_cast<uint8_t>((v>>s)&255U));} void w64(std::vector<uint8_t>&b,uint64_t v){for(uint32_t s=0;s<64U;s+=8U)b.push_back(static_cast<uint8_t>((v>>s)&255U));} uint32_t r32(const uint8_t*p){uint32_t v=0;for(uint32_t s=0;s<32U;s+=8U)v|=static_cast<uint32_t>(p[s/8U])<<s;return v;} uint64_t r64(const uint8_t*p){uint64_t v=0;for(uint32_t s=0;s<64U;s+=8U)v|=static_cast<uint64_t>(p[s/8U])<<s;return v;} bool sz(cnc::Size n,cnc::Size*o)noexcept{if(!o||n>SpecialPowerLedgerCodec::max_entries||n>(std::numeric_limits<cnc::Size>::max()-H)/R)return false;*o=H+n*R;return true;} }}
namespace zero_hour { cnc::Error SpecialPowerLedgerCodec::encode(const SpecialPowerLedger::Snapshot&s,std::vector<uint8_t>*o)noexcept{if(!o)return FT_ERR_INVALID_POINTER;cnc::Size n=static_cast<cnc::Size>(s.cooldowns.size()),z;if(s.schema_version!=1U||!sz(n,&z))return FT_ERR_INVALID_ARGUMENT;try{o->clear();o->reserve(z);w32(*o,1U);w32(*o,static_cast<uint32_t>(n));for(const auto&e:s.cooldowns){if(e.power.value==0U){o->clear();return FT_ERR_INVALID_ARGUMENT;}w64(*o,e.power.value);w64(*o,e.ready_at.value);}}catch(...){o->clear();return FT_ERR_NO_MEMORY;}return FT_ERR_SUCCESS;} cnc::Error SpecialPowerLedgerCodec::decode(const uint8_t*p,cnc::Size n,SpecialPowerLedger::Snapshot*o)noexcept{if(!p||!o)return FT_ERR_INVALID_POINTER;if(n<H)return FT_ERR_INVALID_ARGUMENT;uint32_t c=r32(p+4U);cnc::Size z;if(r32(p)!=1U||!sz(static_cast<cnc::Size>(c),&z)||z!=n)return FT_ERR_CONFIGURATION;SpecialPowerLedger::Snapshot d;try{d.cooldowns.reserve(c);for(uint32_t i=0;i<c;++i){cnc::Size off=H+static_cast<cnc::Size>(i)*R;cnc::DefinitionId power{r64(p+off)};cnc::SimulationTick ready{r64(p+off+8U)};if(power.value==0U||(i&&d.cooldowns.back().power.value>=power.value))return FT_ERR_CONFIGURATION;d.cooldowns.push_back({power,ready});}}catch(...){return FT_ERR_NO_MEMORY;}o->schema_version=1U;o->cooldowns.swap(d.cooldowns);return FT_ERR_SUCCESS;} }
